const e=(t,n=2)=>{const a=10**n;return Math.round((Number(t)+Number.EPSILON)*a)/a};function p(t,n){const a=[];let o=0,r=0;for(const l of t){const g=Number(l.qty)||0,N=Number(l.rate)||0,d=Number(l.discount)||0,x=Number(l.gst_rate)||0,c=Math.max(0,e(g*N-d)),s=e(c*x/100);let u=0,_=0,b=0;n?b=s:(u=e(s/2),_=e(s-u));const h=e(c+s);o+=c,r+=s,a.push({taxable_value:c,cgst_amount:u,sgst_amount:_,igst_amount:b,line_total:h})}o=e(o),r=e(r);const i=o+r,m=Math.round(i),f=e(m-i);return{lines:a,totals:{subtotal:o,tax_total:r,round_off:f,grand_total:m}}}function w(t,n){if(!t)return 0;const a={wholesale:t.wholesale_price,dealer:t.dealer_price,retail:t.retail_price};return Number(a[n]||t.retail_price||t.mrp||0)}export{p as c,w as t};
